package hostinfo

import("os";"os/exec";"path/filepath";"runtime";"strconv";"strings";"github.com/eutelic/runnerhub/internal/core")
func Capacity(path string)core.Resources{return core.Resources{CPUMillis:int64(runtime.NumCPU())*1000,MemoryBytes:memoryBytes(),DiskBytes:diskBytes(path)}}
func memoryBytes()int64{switch runtime.GOOS{case"linux":if b,err:=os.ReadFile("/proc/meminfo");err==nil{for _,line:=range strings.Split(string(b),"\n"){if strings.HasPrefix(line,"MemTotal:"){f:=strings.Fields(line);if len(f)>=2{kb,_:=strconv.ParseInt(f[1],10,64);return kb*1024}}}};case"darwin":if b,err:=exec.Command("sysctl","-n","hw.memsize").Output();err==nil{n,_:=strconv.ParseInt(strings.TrimSpace(string(b)),10,64);return n};case"windows":cmd:=exec.Command("powershell","-NoProfile","-NonInteractive","-Command","[int64](Get-CimInstance Win32_ComputerSystem).TotalPhysicalMemory");if b,err:=cmd.Output();err==nil{n,_:=strconv.ParseInt(strings.TrimSpace(string(b)),10,64);return n}};return 0}
func diskBytes(path string)int64{if strings.TrimSpace(path)==""{path="."};path=existingParent(path);if runtime.GOOS=="windows"{escaped:=strings.ReplaceAll(path,"'","''");script:="$p=(Get-Item -LiteralPath '"+escaped+"').PSDrive; [int64]$p.Free";if b,err:=exec.Command("powershell","-NoProfile","-NonInteractive","-Command",script).Output();err==nil{n,_:=strconv.ParseInt(strings.TrimSpace(string(b)),10,64);return n};return 0};b,err:=exec.Command("df","-Pk",path).Output();if err!=nil{return 0};lines:=strings.Split(strings.TrimSpace(string(b)),"\n");if len(lines)<2{return 0};f:=strings.Fields(lines[len(lines)-1]);if len(f)<4{return 0};availableKB,_:=strconv.ParseInt(f[len(f)-3],10,64);return availableKB*1024}
func existingParent(path string)string{p:=filepath.Clean(path);for{if _,err:=os.Stat(p);err==nil{return p};next:=filepath.Dir(p);if next==p{return "."};p=next}}
